1	//! AgentX subagent for app_moxa_framework (Plan D B).
2	//!
3	//! B1 (Design C): the framework, as an AgentX subagent, FULLY owns the config
4	//! OIDs listed in `lib_moxa_ies_auto_mibs` (the dlmod is removed).
5	//! - GET maps OID -> config-layer URI and reads the value in-process via
6	//!   `config_operation::get_config_from_path` + `remove_password_from_config` —
7	//!   the exact pair the REST `_setting_get` uses (byte-identical, fast).
8	//! - SET reuses the framework's own REST PATCH via `ies_config_set` — the exact
9	//!   loopback path the dlmod used (byte-identical; SET is rare, latency moot).
10	
11	use std::collections::HashMap;
12	use std::os::raw::{c_int, c_uint, c_void};
13	use std::sync::{Arc, Mutex, OnceLock};
14	use std::time::{Duration, Instant};
15	
16	use lib_moxa_rust_ies_auto_mibs::col;
17	use lib_moxa_rust_snmp_agentx as agentx;
18	use plugins_moxa_framework::config::Plugins;
19	use qstring::QString;
20	use rust_moxa_common::config_configs::Configs;
21	use rust_moxa_common::user_info::{UserInfo, UserInfoRole};
22	use rust_moxa_config_layer::config_operation;
23	use rust_moxa_status_operation::StatusOperation;
24	
25	/// How long a per-plugin status snapshot stays valid (mirrors in-master table
26	/// snapshot reuse across a walk). plugin_moxa_io has cache_timeout=0, so without
27	/// this every OID would re-scan hardware.
28	const STATUS_SNAP_TTL: Duration = Duration::from_secs(2);
29	
30	/// Per-plugin status root, refreshed at most once per TTL on the AgentX thread.
31	struct StatusSnap {
32	    /// plugin name -> (fetched_at, plugin status object)
33	    by_plugin: HashMap<String, (Instant, serde_json::Value)>,
34	}
35	
36	/// Live handles into the running framework state, shared with the subagent
37	/// thread (same `Arc<Mutex<…>>` the actix workers use).
38	struct SubagentState {
39	    plugins: Arc<Mutex<Plugins>>,
40	    configs: Arc<Mutex<Configs>>,
41	    status_operation: Arc<Mutex<StatusOperation>>,
42	    plugins_status: Arc<Mutex<plugins_moxa_framework::status::Plugins>>,
43	    status_snap: Mutex<StatusSnap>,
44	}
45	
46	static STATE: OnceLock<SubagentState> = OnceLock::new();
47	
48	/// Fixed read identity for SNMP GETs (Task 5): reads are identity-less — VACM
49	/// authorizes at the master and per-OID config values are uniform. Matches the
50	/// admin identity `LibUtil_CreateToken` bakes for today's SNMP reads.
51	fn sys_read_userinfo() -> UserInfo {
52	    UserInfo {
53	        username: "snmp@moxa^service".to_string(),
54	        role: UserInfoRole::admin,
55	        nonce: String::new(),
56	        from_ip: "127.0.0.1".to_string(),
57	    }
58	}
59	
60	/// First path segment = status plugin name (e.g. "io" from "io/power/system/0").
61	fn status_plugin_name(path: &str) -> Option<&str> {
62	    path.split('/').find(|s| !s.is_empty())
63	}
64	
65	/// Walk `path` under a plugin status root. The first segment is the plugin name
66	/// (already selected); remaining segments index into `root`.
67	fn navigate_plugin_status(root: &serde_json::Value, path: &str) -> serde_json::Value {
68	    let mut cur = root;
69	    let mut skip_plugin = true;
70	    for attr in path.split('/').filter(|s| !s.is_empty()) {
71	        if skip_plugin {
72	            skip_plugin = false;
73	            continue;
74	        }
75	        cur = match attr.parse::<usize>() {
76	            Ok(i) => &cur[i],
77	            Err(_) => &cur[attr],
78	        };
79	        if cur.is_null() {
80	            return serde_json::Value::Null;
81	        }
82	    }
83	    cur.clone()
84	}
85	
86	/// Status GET with a short per-plugin snapshot (fix 2): one `get_status` per
87	/// plugin per TTL, then path navigation in-process — same idea as in-master's
88	/// table snapshot, so a walk does not re-hit hardware for every OID.
89	fn get_status_with_snap(
90	    state: &SubagentState,
91	    path: &str,
92	) -> Result<serde_json::Value, ()> {
93	    let plugin = status_plugin_name(path).ok_or(())?;
94	    {
95	        let snap = state.status_snap.lock().unwrap();
96	        if let Some((at, root)) = snap.by_plugin.get(plugin) {
97	            if at.elapsed() < STATUS_SNAP_TTL {
98	                return Ok(navigate_plugin_status(root, path));
99	            }
100	        }
101	    }
102	
103	    let ui = sys_read_userinfo();
104	    let query = QString::from("");
105	    let root = {
106	        let mut status_op = state.status_operation.lock().unwrap();
107	        let mut plugins_status = state.plugins_status.lock().unwrap();
108	        status_op
109	            .get_status_from_path(&mut plugins_status, plugin, &ui, &query)
110	            .map_err(|_| ())?
111	    };
112	    let value = navigate_plugin_status(&root, path);
113	    state
114	        .status_snap
115	        .lock()
116	        .unwrap()
117	        .by_plugin
118	        .insert(plugin.to_string(), (Instant::now(), root));
119	    Ok(value)
120	}
121	
122	/// Read-only GET handler shared by every registered config OID.
123	fn handle_get(requests: *mut c_void) -> c_int {
124	    let state = match STATE.get() {
125	        Some(s) => s,
126	        None => {
127	            agentx::set_error(requests, agentx::SNMP_ERR_GENERR);
128	            return agentx::SNMP_ERR_NOERROR;
129	        }
130	    };
131	
132	    // 1. the requested OID
133	    let oid = match agentx::get_request_oid(requests) {
134	        Some(o) => o,
135	        None => {
136	            agentx::set_error(requests, agentx::SNMP_ERR_GENERR);
137	            return agentx::SNMP_ERR_NOERROR;
138	        }
139	    };
140	
141	    // 2. OID -> config-layer URI
142	    let entry = match lib_moxa_rust_ies_auto_mibs::lookup_by_oid(&oid) {
143	        Some(e) => e,
144	        None => {
145	            agentx::set_no_such_instance(requests);
146	            return agentx::SNMP_ERR_NOERROR;
147	        }
148	    };
149	
150	    // 2b. table columns:
151	    //   1 = portsPbmp index, 2 = portsPbmp value, 4 = index-table index,
152	    //   6 = RowStatus (ADR-0001).
153	    match entry.table_col {
154	        col::ROW_INDEX => {
155	            let port = *oid.last().unwrap_or(&0) as i64;
156	            agentx::set_int(requests, port);
157	            return agentx::SNMP_ERR_NOERROR;
158	        }
159	        col::PBMP_VALUE => return handle_pbmp_value_get(state, requests, &entry.uri, &oid),
160	        col::IDXTBL_INDEX => {
161	            return handle_idx_table_index_get(
162	                state,
163	                requests,
164	                &entry.uri,
165	                &oid,
166	                entry.is_status,
167	            )
168	        }
169	        col::ROWSTATUS => return handle_rowstatus_get(state, requests, &entry.uri, &oid),
170	        _ => {}
171	    }
172	
173	    // config path: index-table value col (3) -> "<uri><row-1>/<column>";
174	    // turboring ring col (5) -> "<uri>/ring<row>/<column>" (row 1-based);
175	    // a scalar (0) uses the URI as-is.
176	    let idx_path;
177	    let path: &str = if entry.table_col == col::IDXTBL_VALUE {
178	        let row = *oid.last().unwrap_or(&0);
179	        if row < 1 {
180	            agentx::set_no_such_instance(requests);
181	            return agentx::SNMP_ERR_NOERROR;
182	        }
183	        idx_path = format!("{}{}/{}", entry.uri, row - 1, entry.uri_index);
184	        &idx_path
185	    } else if entry.table_col == col::TR2RING_VALUE {
186	        let row = *oid.last().unwrap_or(&0);
187	        if row < 1 {
188	            agentx::set_no_such_instance(requests);
189	            return agentx::SNMP_ERR_NOERROR;
190	        }
191	        idx_path = format!("{}/ring{}/{}", entry.uri, row, entry.uri_index);
192	        &idx_path
193	    } else {
194	        &entry.uri
195	    };
196	
197	    // Status-layer entry (stat/ prefix or URI_STATUS flag): read from the status
198	    // layer at `path` (a scalar's path is the URI; a table's is the row path).
199	    if entry.is_status {
200	        return handle_status_get(state, requests, path, entry.val_type);
201	    }
202	
203	    // 3. read the value in-process — byte-identical to REST `_setting_get`.
204	    //    Lock order (configs then plugins) matches config_layer::setting_read.
205	    let ui = sys_read_userinfo();
206	    let configs = state.configs.lock().unwrap();
207	    let mut plugins = state.plugins.lock().unwrap();
208	
209	    let value = match config_operation::get_config_from_path(
210	        &mut plugins,
211	        &ui,
212	        path,
213	        &configs.running_config,
214	        None,
215	        false,
216	    ) {
217	        Ok(v) => v,
218	        Err(_) => {
219	            // Config path not present (missing row / a URI needing a remap we
220	            // don't apply) -> noSuchInstance so a walk continues.
221	            agentx::set_no_such_instance(requests);
222	            return agentx::SNMP_ERR_NOERROR;
223	        }
224	    };
225	    let value = if value.is_null() {
226	        value
227	    } else {
228	        match config_operation::remove_password_from_config(&mut plugins, path, value) {
229	            Ok(v) => v,
230	            Err(_) => {
231	                agentx::set_no_such_instance(requests);
232	                return agentx::SNMP_ERR_NOERROR;
233	            }
234	        }
235	    };
236	
237	    // 4. set the value per the mapped type (byte-identical to the old handler).
238	    match entry.val_type {
239	        agentx::ASN_INTEGER => {
240	            // Config leaf may be a JSON bool (true->1, false->2, per SNMPv2
241	            // TruthValue == ies-auto-mibs get_value.c:95), a number, or a
242	            // numeric string; accept all three.
243	            let n = value
244	                .as_i64()
245	                .or_else(|| value.as_bool().map(|b| if b { 1 } else { 2 }))
246	                .or_else(|| value.as_str().and_then(|s| s.parse().ok()));
247	            match n {
248	                Some(n) => {
249	                    agentx::set_int(requests, n);
250	                }
251	                None => {
252	                    agentx::set_no_such_instance(requests);
253	                }
254	            }
255	        }
256	        _ => match value.as_str() {
257	            Some(s) => {
258	                agentx::set_octet_string(requests, s);
259	            }
260	            None => {
261	                agentx::set_no_such_instance(requests);
262	            }
263	        },
264	    }
265	    agentx::SNMP_ERR_NOERROR
266	}
267	
268	/// GET for a portsPbmp value column: read the per-port boolean array at `uri`
269	/// and return `array[port-1]` as a TruthValue (true->1, false->2).
270	fn handle_pbmp_value_get(
271	    state: &SubagentState,
272	    requests: *mut c_void,
273	    uri: &str,
274	    oid: &[agentx::Oid],
275	) -> c_int {
276	    let port = match oid.last() {
277	        Some(&p) if p >= 1 => p as usize,
278	        _ => {
279	            agentx::set_no_such_instance(requests);
280	            return agentx::SNMP_ERR_NOERROR;
281	        }
282	    };
283	    let ui = sys_read_userinfo();
284	    let configs = state.configs.lock().unwrap();
285	    let mut plugins = state.plugins.lock().unwrap();
286	    let arr = match config_operation::get_config_from_path(
287	        &mut plugins,
288	        &ui,
289	        uri,
290	        &configs.running_config,
291	        None,
292	        false,
293	    ) {
294	        Ok(v) => v,
295	        Err(_) => {
296	            agentx::set_no_such_instance(requests);
297	            return agentx::SNMP_ERR_NOERROR;
298	        }
299	    };
300	    // `arr` is the JSON boolean array; the SNMP value is array[port-1].
301	    match arr.get(port - 1) {
302	        Some(v) => {
303	            let n = v
304	                .as_bool()
305	                .map(|b| if b { 1 } else { 2 })
306	                .or_else(|| v.as_i64());
307	            match n {
308	                Some(n) => {
309	                    agentx::set_int(requests, n);
310	                }
311	                None => {
312	                    agentx::set_no_such_instance(requests);
313	                }
314	            }
315	        }
316	        None => {
317	            agentx::set_no_such_instance(requests);
318	        }
319	    }
320	    agentx::SNMP_ERR_NOERROR
321	}
322	
323	/// SET for a portsPbmp value column: read the per-port boolean array, flip
324	/// `array[port-1]` to the incoming TruthValue (1 -> true, else -> false), and
325	/// PATCH the whole array back. Returns 0 on success, non-zero on failure.
326	fn handle_pbmp_value_set(uri: &str, requests: *mut c_void) -> i32 {
327	    let state = match STATE.get() {
328	        Some(s) => s,
329	        None => return -1,
330	    };
331	    let oid = match agentx::get_request_oid(requests) {
332	        Some(o) => o,
333	        None => return -1,
334	    };
335	    let port = match oid.last() {
336	        Some(&p) if p >= 1 => p as usize,
337	        _ => return -1,
338	    };
339	    let sv = match agentx::get_set_int(requests) {
340	        Some(v) => v,
341	        None => return -1,
342	    };
343	
344	    // Read the current array (lock order: configs then plugins).
345	    let mut bools: Vec<bool> = {
346	        let ui = sys_read_userinfo();
347	        let configs = state.configs.lock().unwrap();
348	        let mut plugins = state.plugins.lock().unwrap();
349	        let arr = match config_operation::get_config_from_path(
350	            &mut plugins,
351	            &ui,
352	            uri,
353	            &configs.running_config,
354	            None,
355	            false,
356	        ) {
357	            Ok(v) => v,
358	            Err(_) => return -1,
359	        };
360	        match arr.as_array() {
361	            Some(a) => a.iter().map(|v| v.as_bool().unwrap_or(false)).collect(),
362	            None => return -1,
363	        }
364	    };
365	    if port - 1 >= bools.len() {
366	        return -1;
367	    }
368	    bools[port - 1] = sv == 1;
369	
370	    // Serialize "[true,false,…]" by hand (no serde_json dep) and PATCH it whole.
371	    let json = format!(
372	        "[{}]",
373	        bools
374	            .iter()
375	            .map(|b| if *b { "true" } else { "false" })
376	            .collect::<Vec<_>>()
377	            .join(",")
378	    );
379	    lib_moxa_rust_ies_auto_mibs::config_set_json(uri, &json)
380	}
381	
382	/* SNMP RowStatus (RFC 2579) — same integers as MOXA_SNMP_READ_CREATE_*. */
383	const RS_ACTIVE: i64 = 1;
384	const RS_NOT_IN_SERVICE: i64 = 2;
385	const RS_CREATE_AND_GO: i64 = 4;
386	const RS_CREATE_AND_WAIT: i64 = 5;
387	const RS_DESTROY: i64 = 6;
388	
389	/// Config array path for an index-table URI base (`"snmpTrap/host/"` -> `"snmpTrap/host"`).
390	fn index_table_array_uri(uri: &str) -> &str {
391	    uri.strip_suffix('/').unwrap_or(uri)
392	}
393	
394	fn read_config_value(state: &SubagentState, path: &str) -> Result<serde_json::Value, ()> {
395	    let ui = sys_read_userinfo();
396	    let configs = state.configs.lock().unwrap();
397	    let mut plugins = state.plugins.lock().unwrap();
398	    config_operation::get_config_from_path(
399	        &mut plugins,
400	        &ui,
401	        path,
402	        &configs.running_config,
403	        None,
404	        false,
405	    )
406	    .map_err(|_| ())
407	}
408	
409	/// GET RowStatus: missing row -> noSuchInstance; `valid` true/absent -> active(1);
410	/// `valid` false -> notInService(2). Mirrors in-master mapping onto config `valid`.
411	fn handle_rowstatus_get(
412	    state: &SubagentState,
413	    requests: *mut c_void,
414	    uri: &str,
415	    oid: &[agentx::Oid],
416	) -> c_int {
417	    let row = match oid.last() {
418	        Some(&r) if r >= 1 => r as usize,
419	        _ => {
420	            agentx::set_no_such_instance(requests);
421	            return agentx::SNMP_ERR_NOERROR;
422	        }
423	    };
424	    let arr_uri = index_table_array_uri(uri);
425	    let arr = match read_config_value(state, arr_uri) {
426	        Ok(v) => v,
427	        Err(_) => {
428	            agentx::set_no_such_instance(requests);
429	            return agentx::SNMP_ERR_NOERROR;
430	        }
431	    };
432	    let Some(host) = arr.get(row - 1) else {
433	        agentx::set_no_such_instance(requests);
434	        return agentx::SNMP_ERR_NOERROR;
435	    };
436	    if host.is_null() {
437	        agentx::set_no_such_instance(requests);
438	        return agentx::SNMP_ERR_NOERROR;
439	    }
440	    let rs = match host.get("valid").and_then(|v| v.as_bool()) {
441	        Some(false) => RS_NOT_IN_SERVICE,
442	        _ => RS_ACTIVE,
443	    };
444	    agentx::set_int(requests, rs);
445	    agentx::SNMP_ERR_NOERROR
446	}
447	
448	fn default_trap_host(valid: bool) -> serde_json::Value {
449	    serde_json::json!({
450	        "hostName": null,
451	        "mode": null,
452	        "v1v2cCommunity": null,
453	        "valid": valid,
454	    })
455	}
456	
457	/// SET RowStatus: createAndGo/Wait pad up to the SNMP index; destroy removes;
458	/// active/notInService flip `valid`. Whole-array PATCH like portsPbmp.
459	fn handle_rowstatus_set(uri: &str, requests: *mut c_void) -> i32 {
460	    let state = match STATE.get() {
461	        Some(s) => s,
462	        None => return -1,
463	    };
464	    let oid = match agentx::get_request_oid(requests) {
465	        Some(o) => o,
466	        None => return -1,
467	    };
468	    let row = match oid.last() {
469	        Some(&r) if r >= 1 => r as usize,
470	        _ => return -1,
471	    };
472	    let cmd = match agentx::get_set_int(requests) {
473	        Some(v) => v,
474	        None => return -1,
475	    };
476	    let arr_uri = index_table_array_uri(uri);
477	    let max_rows = if arr_uri == "snmpTrap/host" { 2 } else { 16 };
478	    if row > max_rows {
479	        return -1;
480	    }
481	
482	    let mut hosts: Vec<serde_json::Value> = match read_config_value(state, arr_uri) {
483	        Ok(v) => match v.as_array() {
484	            Some(a) => a.clone(),
485	            None => return -1,
486	        },
487	        Err(_) => Vec::new(),
488	    };
489	
490	    match cmd {
491	        RS_ACTIVE | RS_NOT_IN_SERVICE => {
492	            if row - 1 >= hosts.len() {
493	                return -1;
494	            }
495	            if let Some(obj) = hosts[row - 1].as_object_mut() {
496	                obj.insert("valid".into(), serde_json::Value::Bool(cmd == RS_ACTIVE));
497	            } else {
498	                return -1;
499	            }
500	        }
501	        RS_CREATE_AND_GO | RS_CREATE_AND_WAIT => {
502	            let valid = cmd == RS_CREATE_AND_GO;
503	            while hosts.len() < row {
504	                hosts.push(default_trap_host(false));
505	            }
506	            if let Some(obj) = hosts[row - 1].as_object_mut() {
507	                obj.insert("valid".into(), serde_json::Value::Bool(valid));
508	            } else {
509	                hosts[row - 1] = default_trap_host(valid);
510	            }
511	        }
512	        RS_DESTROY => {
513	            if row - 1 >= hosts.len() {
514	                return -1;
515	            }
516	            hosts.remove(row - 1);
517	        }
518	        _ => return -1,
519	    }
520	
521	    let json = match serde_json::to_string(&hosts) {
522	        Ok(s) => s,
523	        Err(_) => return -1,
524	    };
525	    lib_moxa_rust_ies_auto_mibs::config_set_json(arr_uri, &json)
526	}
527	
528	/// GET for a config index-table index column: the value is the row number, but
529	/// only for rows that exist (the fixed-size array element "<uri><row-1>" is
530	/// present). Rows past the array end -> noSuchInstance.
531	fn handle_idx_table_index_get(
532	    state: &SubagentState,
533	    requests: *mut c_void,
534	    uri: &str,
535	    oid: &[agentx::Oid],
536	    is_status: bool,
537	) -> c_int {
538	    let row = match oid.last() {
539	        Some(&r) if r >= 1 => r,
540	        _ => {
541	            agentx::set_no_such_instance(requests);
542	            return agentx::SNMP_ERR_NOERROR;
543	        }
544	    };
545	    let path = format!("{}{}", uri, row - 1);
546	    // Row exists iff the array element "<uri><row-1>" resolves (config or status).
547	    let exists = if is_status {
548	        matches!(get_status_with_snap(state, &path), Ok(ref v) if !v.is_null())
549	    } else {
550	        let ui = sys_read_userinfo();
551	        let configs = state.configs.lock().unwrap();
552	        let mut plugins = state.plugins.lock().unwrap();
553	        matches!(
554	            config_operation::get_config_from_path(
555	                &mut plugins,
556	                &ui,
557	                &path,
558	                &configs.running_config,
559	                None,
560	                false,
561	            ),
562	            Ok(ref v) if !v.is_null()
563	        )
564	    };
565	    if exists {
566	        agentx::set_int(requests, row as i64);
567	    } else {
568	        agentx::set_no_such_instance(requests);
569	    }
570	    agentx::SNMP_ERR_NOERROR
571	}
572	
573	/// GET for a status-layer scalar: read `path` from the status layer (parallel to
574	/// config_operation for config OIDs) and set the value per the mapped SNMP type.
575	fn handle_status_get(
576	    state: &SubagentState,
577	    requests: *mut c_void,
578	    path: &str,
579	    val_type: c_int,
580	) -> c_int {
581	    let value = match get_status_with_snap(state, path) {
582	        Ok(v) => v,
583	        Err(_) => {
584	            agentx::set_no_such_instance(requests);
585	            return agentx::SNMP_ERR_NOERROR;
586	        }
587	    };
588	    match val_type {
589	        agentx::ASN_INTEGER => {
590	            let n = value
591	                .as_i64()
592	                .or_else(|| value.as_bool().map(|b| if b { 1 } else { 2 }))
593	                .or_else(|| {
594	                    value.as_str().and_then(|s| match s {
595	                        // plugin_moxa_io Status.status strings
596	                        "on" | "true" => Some(1),
597	                        "off" | "false" => Some(2),
598	                        other => other.parse().ok(),
599	                    })
600	                });
601	            match n {
602	                Some(n) => {
603	                    agentx::set_int(requests, n);
604	                }
605	                None => {
606	                    agentx::set_no_such_instance(requests);
607	                }
608	            }
609	        }
610	        _ => match value.as_str() {
611	            Some(s) => {
612	                agentx::set_octet_string(requests, s);
613	            }
614	            None => {
615	                agentx::set_no_such_instance(requests);
616	            }
617	        },
618	    }
619	    agentx::SNMP_ERR_NOERROR
620	}
621	
622	/// Look up the mapping entry for the OID a request targets.
623	fn request_entry(requests: *mut c_void) -> Option<lib_moxa_rust_ies_auto_mibs::MapEntry> {
624	    let oid = agentx::get_request_oid(requests)?;
625	    lib_moxa_rust_ies_auto_mibs::lookup_by_oid(&oid)
626	}
627	
628	/// Write handler (Design C): SET reuses the framework's own REST PATCH via
629	/// `ies_config_set`, byte-identical to the dlmod. Called in MODE_SET_ACTION.
630	fn handle_set(requests: *mut c_void) -> c_int {
631	    let entry = match request_entry(requests) {
632	        Some(e) => e,
633	        None => {
634	            agentx::set_error(requests, agentx::SNMP_ERR_COMMITFAILED);
635	            return agentx::SNMP_ERR_NOERROR;
636	        }
637	    };
638	    // Read-only: index columns and status-layer entries.
639	    if entry.table_col == col::ROW_INDEX
640	        || entry.table_col == col::IDXTBL_INDEX
641	        || entry.is_status
642	    {
643	        agentx::set_error(requests, agentx::SNMP_ERR_NOTWRITABLE);
644	        return agentx::SNMP_ERR_NOERROR;
645	    }
646	    // portsPbmp value column: whole-array read-modify-write.
647	    if entry.table_col == col::PBMP_VALUE {
648	        let rc = handle_pbmp_value_set(&entry.uri, requests);
649	        if rc != 0 {
650	            agentx::set_error(requests, agentx::SNMP_ERR_COMMITFAILED);
651	        }
652	        return agentx::SNMP_ERR_NOERROR;
653	    }
654	    // RowStatus: create/destroy / valid (ADR-0001); not a config leaf path.
655	    if entry.table_col == col::ROWSTATUS {
656	        let rc = handle_rowstatus_set(&entry.uri, requests);
657	        if rc != 0 {
658	            agentx::set_error(requests, agentx::SNMP_ERR_COMMITFAILED);
659	        }
660	        return agentx::SNMP_ERR_NOERROR;
661	    }
662	
663	    // Scalar (0) or a path-addressable value column (index-table / turboring ring):
664	    // SET writes the field directly (no read-modify-write).
665	    let idx_path;
666	    let path: &str = if entry.table_col == col::IDXTBL_VALUE
667	        || entry.table_col == col::TR2RING_VALUE
668	    {
669	        match agentx::get_request_oid(requests).and_then(|o| o.last().copied()) {
670	            Some(row) if row >= 1 => {
671	                idx_path = if entry.table_col == col::TR2RING_VALUE {
672	                    format!("{}/ring{}/{}", entry.uri, row, entry.uri_index)
673	                } else {
674	                    format!("{}{}/{}", entry.uri, row - 1, entry.uri_index)
675	                };
676	                &idx_path
677	            }
678	            _ => {
679	                agentx::set_error(requests, agentx::SNMP_ERR_COMMITFAILED);
680	                return agentx::SNMP_ERR_NOERROR;
681	            }
682	        }
683	    } else {
684	        &entry.uri
685	    };
686	
687	    let rc = match entry.val_type {
688	        agentx::ASN_INTEGER => match agentx::get_set_int(requests) {
689	            None => -1,
690	            Some(sv) => {
691	                // A config field exposed as SNMP INTEGER may be stored as a JSON
692	                // boolean (enable/trap/…). Read its current type and write back
693	                // the matching one: TruthValue 1 -> true, anything else -> false.
694	                if config_field_is_bool(path) {
695	                    lib_moxa_rust_ies_auto_mibs::config_set_bool(path, sv == 1)
696	                } else {
697	                    lib_moxa_rust_ies_auto_mibs::config_set_int(path, sv)
698	                }
699	            }
700	        },
701	        _ => match agentx::get_set_string(requests) {
702	            Some(s) => lib_moxa_rust_ies_auto_mibs::config_set(path, &s),
703	            None => -1,
704	        },
705	    };
706	    if rc != 0 {
707	        agentx::set_error(requests, agentx::SNMP_ERR_COMMITFAILED);
708	    }
709	    agentx::SNMP_ERR_NOERROR
710	}
711	
712	/// True if the config leaf at `uri` is currently a JSON boolean (so a SET should
713	/// write a boolean, not a number).
714	fn config_field_is_bool(uri: &str) -> bool {
715	    let state = match STATE.get() {
716	        Some(s) => s,
717	        None => return false,
718	    };
719	    let ui = sys_read_userinfo();
720	    let configs = state.configs.lock().unwrap();
721	    let mut plugins = state.plugins.lock().unwrap();
722	    config_operation::get_config_from_path(
723	        &mut plugins,
724	        &ui,
725	        uri,
726	        &configs.running_config,
727	        None,
728	        false,
729	    )
730	    .map(|v| v.is_boolean())
731	    .unwrap_or(false)
732	}
733	
734	/// Dispatch by net-snmp mode: GET in-process, SET via loopback REST PATCH.
735	fn dispatch(reqinfo: *mut c_void, requests: *mut c_void) -> c_int {
736	    match agentx::get_mode(reqinfo) {
737	        agentx::MODE_GET => handle_get(requests),
738	        agentx::MODE_SET_RESERVE1 => {
739	            let entry = request_entry(requests);
740	            // Index columns (portsPbmp portIndex = 1, index-table index = 4) are
741	            // read-only; value columns (2, 3) are writable (MODE_SET_ACTION).
742	            if entry
743	                .as_ref()
744	                .map(|e| {
745	                    e.table_col == col::ROW_INDEX
746	                        || e.table_col == col::IDXTBL_INDEX
747	                        || e.is_status
748	                })
749	                .unwrap_or(false)
750	            {
751	                agentx::set_error(requests, agentx::SNMP_ERR_NOTWRITABLE);
752	                return agentx::SNMP_ERR_NOERROR;
753	            }
754	            // Reject a SET whose type doesn't match the mapped OID's type.
755	            let expected = match entry {
756	                Some(e) if e.val_type == agentx::ASN_INTEGER => agentx::ASN_INTEGER,
757	                _ => agentx::ASN_OCTET_STR,
758	            };
759	            if agentx::get_var_type(requests) != expected {
760	                agentx::set_error(requests, agentx::SNMP_ERR_WRONGTYPE);
761	            }
762	            agentx::SNMP_ERR_NOERROR
763	        }
764	        agentx::MODE_SET_ACTION => handle_set(requests),
765	        // RESERVE2 / COMMIT / FREE / UNDO: nothing to do (action already applied).
766	        _ => agentx::SNMP_ERR_NOERROR,
767	    }
768	}
769	
770	/// net-snmp `Netsnmp_Node_Handler`. Panics must never cross into C, so the body
771	/// runs under catch_unwind and degrades to genErr.
772	extern "C" fn moxa_config_handler(
773	    _handler: *mut c_void,
774	    _reginfo: *mut c_void,
775	    reqinfo: *mut c_void,
776	    requests: *mut c_void,
777	) -> c_int {
778	    let res =
779	        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| dispatch(reqinfo, requests)));
780	    match res {
781	        Ok(code) => code,
782	        Err(_) => {
783	            agentx::set_error(requests, agentx::SNMP_ERR_GENERR);
784	            agentx::SNMP_ERR_NOERROR
785	        }
786	    }
787	}
788	
789	/// Parse a dotted IPv4 string ("192.168.1.5") to 4 bytes. None if malformed.
790	fn ipv4_to_bytes(s: &str) -> Option<[u8; 4]> {
791	    let mut out = [0u8; 4];
792	    let mut n = 0usize;
793	    for part in s.split('.') {
794	        if n >= 4 {
795	            return None;
796	        }
797	        out[n] = part.parse::<u8>().ok()?;
798	        n += 1;
799	    }
800	    if n == 4 {
801	        Some(out)
802	    } else {
803	        None
804	    }
805	}
806	
807	/// trustedIp table OID (the table object; entry = ROOT.1, columns ROOT.1.c.row).
808	const TRUSTEDIP_ROOT: &[agentx::Oid] = &[1, 3, 6, 1, 4, 1, 8691, 602, 1, 4, 1, 2];
809	
810	/// Live row count of the trustedIp config array (net-snmp iterator polls this on
811	/// every walk). 0 on any error -> empty table.
812	fn trustedip_rows() -> Vec<serde_json::Value> {
813	    let Some(state) = STATE.get() else {
814	        return Vec::new();
815	    };
816	    match read_config_value(state, "trustedAccess/trustedIp") {
817	        Ok(v) => v.as_array().cloned().unwrap_or_default(),
818	        Err(_) => Vec::new(),
819	    }
820	}
821	
822	extern "C" fn trustedip_row_count() -> c_uint {
823	    trustedip_rows().len() as c_uint
824	}
825	
826	/// Plan E (ADR-0003, refresh-gap fix): net-snmp `table_iterator` node handler for
827	/// trustedIp. Reads the CURRENT config each request (no startup snapshot), so GET
828	/// reflects config changes with no reboot. Columns: 1=index(INTEGER),
829	/// 2=ipAddress(IPADDRESS), 3=netmask(IPADDRESS), 4=rowStatus(INTEGER
830	/// active(1)/notInService(2)) — byte-identical to the old table_data_set. GET-only
831	/// (RONLY); SET stays in-master.
832	extern "C" fn trustedip_iter_handler(
833	    _handler: *mut c_void,
834	    _reginfo: *mut c_void,
835	    _reqinfo: *mut c_void,
836	    requests: *mut c_void,
837	) -> c_int {
838	    let oid = match agentx::get_request_oid(requests) {
839	        Some(o) => o,
840	        None => {
841	            agentx::set_no_such_instance(requests);
842	            return agentx::SNMP_ERR_NOERROR;
843	        }
844	    };
845	    // Instance OID = ROOT + [1 (entry), col, row]; net-snmp resolved it already.
846	    let rl = TRUSTEDIP_ROOT.len();
847	    if oid.len() < rl + 3 {
848	        agentx::set_no_such_instance(requests);
849	        return agentx::SNMP_ERR_NOERROR;
850	    }
851	    let col = oid[rl + 1];
852	    let row = oid[oid.len() - 1] as usize;
853	
854	    let rows = trustedip_rows();
855	    let Some(item) = rows.get(row.wrapping_sub(1)) else {
856	        agentx::set_no_such_instance(requests);
857	        return agentx::SNMP_ERR_NOERROR;
858	    };
859	    match col {
860	        1 => {
861	            agentx::set_int(requests, row as i64);
862	        }
863	        2 => match item.get("ipAddress").and_then(|v| v.as_str()).and_then(ipv4_to_bytes) {
864	            Some(b) => {
865	                agentx::set_ipaddress(requests, &b);
866	            }
867	            None => {
868	                agentx::set_no_such_instance(requests);
869	            }
870	        },
871	        3 => match item.get("netmask").and_then(|v| v.as_str()).and_then(ipv4_to_bytes) {
872	            Some(b) => {
873	                agentx::set_ipaddress(requests, &b);
874	            }
875	            None => {
876	                agentx::set_no_such_instance(requests);
877	            }
878	        },
879	        4 => {
880	            // Mirror in-master / handle_rowstatus_get: valid==false -> notInService,
881	            // else (true or absent) -> active.
882	            let rs = match item.get("valid").and_then(|v| v.as_bool()) {
883	                Some(false) => RS_NOT_IN_SERVICE,
884	                _ => RS_ACTIVE,
885	            };
886	            agentx::set_int(requests, rs);
887	        }
888	        _ => {
889	            agentx::set_no_such_instance(requests);
890	        }
891	    }
892	    agentx::SNMP_ERR_NOERROR
893	}
894	
895	/// Register trustedIp as a LIVE read-only `table_iterator` (index INTEGER, cols
896	/// 1..4). Replaces the startup-snapshot table_data_set so config changes show up
897	/// in SNMP GET without a reboot.
898	fn register_trustedip_table() {
899	    agentx::register_iter_table(
900	        "trustedIpTable",
901	        TRUSTEDIP_ROOT,
902	        agentx::ASN_INTEGER,
903	        1,
904	        4,
905	        trustedip_row_count,
906	        trustedip_iter_handler,
907	    );
908	}
909	
910	/// Start the AgentX subagent on its own thread (non-blocking). Registers every
911	/// mapped config OID read-only and connects to the snmpd master.
912	pub fn start_snmp_subagent(
913	    plugins: Arc<Mutex<Plugins>>,
914	    configs: Arc<Mutex<Configs>>,
915	    status_operation: Arc<Mutex<StatusOperation>>,
916	    plugins_status: Arc<Mutex<plugins_moxa_framework::status::Plugins>>,
917	) {
918	    let _ = STATE.set(SubagentState {
919	        plugins,
920	        configs,
921	        status_operation,
922	        plugins_status,
923	        status_snap: Mutex::new(StatusSnap {
924	            by_plugin: HashMap::new(),
925	        }),
926	    });
927	
928	    agentx::init("app_moxa_framework");
929	    // Plan E (ADR-0003): trustedIp served as ONE LIVE read-only table_iterator
930	    // (net-snmp sequences GET/GETNEXT/GETBULK; reads config per request so no
931	    // reboot needed); SET stays in-master. Its per-OID regs are skipped below —
932	    // the iterator owns the whole subtree.
933	    register_trustedip_table();
934	    for oid in lib_moxa_rust_ies_auto_mibs::all_oids() {
935	        let under_trustedip = oid.len() > TRUSTEDIP_ROOT.len()
936	            && oid.iter().zip(TRUSTEDIP_ROOT.iter()).all(|(a, b)| a == b);
937	        if under_trustedip {
938	            continue; // served by the table_iterator registered above
939	        }
940	        agentx::register_instance(
941	            "moxaIesConfig",
942	            &oid,
943	            agentx::HANDLER_CAN_RWRITE,
944	            moxa_config_handler,
945	        );
946	    }
947	    agentx::run_in_thread();
948	}
