              ies_auto_mibs_setup_entry_flags_mx_turboring_v2),
    REUSE_SRC(mx_deviceIO_MibEntry,
              ies_auto_mibs_setup_entry_flags_net_mx_deviceIO),
    /* RowStatus handled as IES_COL_ROWSTATUS in the framework (ADR-0001);
     * in-master READ_CREATE_v2 flags are unused on this path. */
    REUSE_SRC(mxTrap_MibEntry, NULL),
    /* Plan E (ADR-0003): trustAccess is dual-registered — framework serves GET
     * here, but in-master KEEPS MOX_SNMP_INIT_ENTRY(mxSysTrustAccess_MibEntry)
     * so SET (incl. trustedIp RowStatus create/destroy) stays in-master and wins
     * the wire by priority. Do NOT comment out its INIT_ENTRY. RowStatus col in
     * framework is GET-only (active/notInService); framework SET is never hit. */
    REUSE_SRC(mxSysTrustAccess_MibEntry, NULL),
};

