/// snmpTrap host table OID (the table object; entry = ROOT.1, columns ROOT.1.c.row).
const SNMPTRAP_HOST_ROOT: &[agentx::Oid] = &[1, 3, 6, 1, 4, 1, 8691, 602, 7, 2, 1, 3];

/// Live rows of the `snmpTrap/host` config array (net-snmp iterator polls the
/// count on every walk). Empty on any error -> empty table. maxItems 2 (schema).
fn snmptrap_host_rows() -> Vec<serde_json::Value> {
    let Some(state) = STATE.get() else {
        return Vec::new();
    };
    match read_config_value(state, "snmpTrap/host") {
        Ok(v) => v.as_array().cloned().unwrap_or_default(),
        Err(_) => Vec::new(),
    }
}

extern "C" fn snmptrap_host_row_count() -> c_uint {
    snmptrap_host_rows().len() as c_uint
}

/// Plan E (ADR-0006): net-snmp `table_iterator` node handler for the snmpTrap host
/// table. Reads the CURRENT config each request (no startup snapshot), so GET
/// reflects config changes with no reboot. Columns: 1=index(INTEGER),
/// 2=hostName(OCTET STRING), 3=mode(INTEGER 1..5), 4=v1v2cCommunity(OCTET STRING),
/// 5=rowStatus(INTEGER active(1)/notInService(2)). GET-only (RONLY); SET (incl.
/// rowStatus createAndGo/destroy) stays in-master via readCreate_v2_mxTrap_host.c.
extern "C" fn snmptrap_host_iter_handler(
    _handler: *mut c_void,
    _reginfo: *mut c_void,
    _reqinfo: *mut c_void,
    requests: *mut c_void,
) -> c_int {
    let oid = match agentx::get_request_oid(requests) {
        Some(o) => o,
        None => {
            agentx::set_no_such_instance(requests);
            return agentx::SNMP_ERR_NOERROR;
        }
    };
    // Instance OID = ROOT + [1 (entry), col, row]; net-snmp resolved it already.
    let rl = SNMPTRAP_HOST_ROOT.len();
    if oid.len() < rl + 3 {
        agentx::set_no_such_instance(requests);
        return agentx::SNMP_ERR_NOERROR;
    }
    let col = oid[rl + 1];
    let row = oid[oid.len() - 1] as usize;

    let rows = snmptrap_host_rows();
    let Some(item) = rows.get(row.wrapping_sub(1)) else {
        agentx::set_no_such_instance(requests);
        return agentx::SNMP_ERR_NOERROR;
    };
    match col {
        1 => {
            agentx::set_int(requests, row as i64);
        }
        2 => match item.get("hostName").and_then(|v| v.as_str()) {
            Some(s) => {
                agentx::set_octet_string(requests, s);
            }
            None => {
                agentx::set_no_such_instance(requests);
            }
        },
        3 => match item.get("mode").and_then(|v| v.as_i64()) {
            Some(n) => {
                agentx::set_int(requests, n);
            }
            None => {
                agentx::set_no_such_instance(requests);
            }
        },
        4 => match item.get("v1v2cCommunity").and_then(|v| v.as_str()) {
            Some(s) => {
                agentx::set_octet_string(requests, s);
            }
            None => {
                agentx::set_no_such_instance(requests);
            }
        },
        5 => {
            // Mirror in-master / handle_rowstatus_get: valid==false -> notInService,
            // else (true or absent) -> active.
            let rs = match item.get("valid").and_then(|v| v.as_bool()) {
                Some(false) => RS_NOT_IN_SERVICE,
                _ => RS_ACTIVE,
            };
            agentx::set_int(requests, rs);
        }
        _ => {
            agentx::set_no_such_instance(requests);
        }
    }
    agentx::SNMP_ERR_NOERROR
}

/// Register the snmpTrap host table as a LIVE read-only `table_iterator` (index
/// INTEGER, cols 1..5). Plan E (ADR-0006): GET served live here; SET (rowStatus
/// createAndGo/destroy) stays in-master. The 2 scalars (informRetries/Timeout,
/// .602.7.2.1.1/.2) are NOT under this ROOT and stay framework-served (Plan D).
fn register_snmptrap_host_table() {
    agentx::register_iter_table(
        "snmpTrapHostTable",
        SNMPTRAP_HOST_ROOT,
        agentx::ASN_INTEGER,
        1,
        5,
        snmptrap_host_row_count,
        snmptrap_host_iter_handler,
    );
}

