/// Live rows of the `ipInterface/l3VlanIfTable` config array (net-snmp iterator
/// polls the count on every walk). Empty on any error -> empty table (maxItems 256).
fn l3vlanif_rows() -> Vec<serde_json::Value> {
    let Some(state) = STATE.get() else {
        return Vec::new();
    };
    match read_config_value(state, "ipInterface/l3VlanIfTable") {
        Ok(v) => v.as_array().cloned().unwrap_or_default(),
        Err(_) => Vec::new(),
    }
}

extern "C" fn l3vlanif_row_count() -> c_uint {
    l3vlanif_rows().len() as c_uint
}

/// Render a config field as SNMP INTEGER, mirroring the in-master / generic
/// handler: JSON number as-is, JSON bool -> TruthValue (true->1, false->2).
/// `None` -> noSuchInstance.
